from itertools import combinations
edges = [(0,2),(0,4),(0,5),(1,2),(1,4),(1,5),(2,3),(3,4),(3,5)]
E = set(edges)
def has_tri(E):
    for a,b,c in combinations(range(6),3):
        if (a,b) in E and (b,c) in E and (a,c) in E: return True
    return False
print("triangle-free:", not has_tri(E))
# maximal check
for u,v in combinations(range(6),2):
    if (u,v) not in E:
        E2 = E | {(u,v)}
        if not has_tri(E2):
            print("not maximal, can add", (u,v)); break
else:
    print("maximal")
print("(3,5) in E:", (3,5) in E)
